      const res = await fetch(`${API_BASE}/${phone}/messages`);
      const data = await res.json();
      if (data.success && data.data) {
        // Group messages by contact
        const newChatMsgs = {};
        data.data.forEach(m => {
          const contactPhone = m.sender_phone === phone ? m.receiver_phone : m.sender_phone;
          if (!newChatMsgs[contactPhone]) newChatMsgs[contactPhone] = [];

          newChatMsgs[contactPhone].push({
            id: m.id,
            sender: m.sender_phone === phone ? 'You' : (chatContacts.find(c => c.phone === contactPhone)?.name || contactPhone),
            message: m.content,
            media_url: m.media_url,
            time: new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMine: m.sender_phone === phone,
            status: 'sent',
            timestamp: m.timestamp
          });
        });

        // Sort each contact's messages
        Object.keys(newChatMsgs).forEach(k => {
          newChatMsgs[k].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
        });

        setChatMessages(prev => {
          // Only update if there's a difference to avoid unnecessary re-renders
