  // ============================================
  const handleLoginSubmit = async () => {
    setOtpError('');
    const trimmedPhone = loginPhone.trim();
    if (!trimmedPhone || !loginPassword.trim()) {
      setOtpError('Please enter your Phone Number and Password.');
      return;
    }
    if (!validateKenyanPhone(trimmedPhone)) {
      setOtpError('Invalid Kenyan phone number. e.g. 0712345678, +2547...');
      return;
    }
    setIsVerifyingOtp(true); // Reusing this loading state
    try {
      const res = await fetch(`${API_BASE}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          phone_number: loginPhone.trim(), 
          password: loginPassword.trim() 
        })
      });
      const data = await res.json();
      if (data.status === 'otp_sent') {
        setOtpSent(true);
        setOtpTimerSeconds(180);
        setCanResendOtp(false);
        setResendCountdown(30);
        setLoginOtp('');
        setOtpSuccess(data.message || 'OTP sent! Please check the console.');
      } else if (data.status === 'force_reset') {
        setIsForgotPassword(true);
        setOtpSent(true);
        setOtpTimerSeconds(180);
        setCanResendOtp(false);
        setResendCountdown(30);
        setLoginOtp('');
        setOtpSuccess(data.message || 'Incorrect password. OTP sent for reset.');
      } else {
        setOtpError(data.message || 'Invalid credentials.');
      }
    } catch {
      setOtpError('Network error. Please try again.');
    } finally {
      setIsVerifyingOtp(false);
    }
  };

