  const handleVerifyLoginOtp = async () => {
    setOtpError('');
    if (!loginOtp.trim() || loginOtp.trim().length !== 6) {
      setOtpError('Please enter the 6-digit OTP.');
      return;
    }
    setIsVerifyingOtp(true);
