  const handleResetPasswordSubmit = async () => {
    setOtpError('');
    if (!loginOtp.trim() || loginOtp.trim().length !== 6) {
      setOtpError('Please enter the 6-digit OTP.');
      return;
    }
    if (!resetPassword.trim()) {
      setOtpError('Please provide a new password.');
      return;
    }

    // Validate strong password if provided
    if (resetPassword.trim()) {
      const strongPwdRegex = /^(?=.*[a-zA-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{10,}$/;
      if (!strongPwdRegex.test(resetPassword.trim())) {
        setOtpError('Password must be at least 10 characters and contain numbers, letters, and special characters.');
        return;
      }
    }

    setIsVerifyingOtp(true);
    try {
      const res = await fetch(`${API_BASE}/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
