  const sendMessage = async () => {
    if ((!newMessage.trim() && !chatMediaFile) || !selectedChatContact) return;

    let mediaUrlToSend = null;
    let newMsg = null;

    // Optimistic UI update
    newMsg = {
      id: Date.now(),
      sender: 'You',
      message: newMessage,
      media_url: chatMediaPreview,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMine: true,
      status: 'sending'
    };

    setChatMessages(prev => ({
      ...prev,
      [selectedChatContact.phone]: [...(prev[selectedChatContact.phone] || []), newMsg]
    }));

    setChatContacts(prev => prev.map(c => 
      c.phone === selectedChatContact.phone 
        ? { ...c, lastMessage: chatMediaFile ? '📷 Photo' : newMessage, lastMessageTime: 'Now', unread: 0 }
        : c
    ));

    setIsSendingMessage(true);
    const messageToSend = newMessage;
    setNewMessage('');

    try {
      const fromPhone = currentUser?.phone || myPhone;

      // Upload media if present
      if (chatMediaFile) {
        const formData = new FormData();
        formData.append('file', chatMediaFile);

        const uploadRes = await fetch(`${API_BASE}/${fromPhone}/upload-media`, {
          method: 'POST',
          body: formData
        });
        const uploadData = await uploadRes.json();

        if (uploadData.success) {
          mediaUrlToSend = uploadData.url;
        } else {
          addNotification('❌ Failed to upload photo.', 'error');
          setIsSendingMessage(false);
          return;
        }
      }

      setChatMediaFile(null);
      setChatMediaPreview(null);

      const payload = { to_phone: selectedChatContact.phone };
      if (messageToSend.trim()) payload.message = messageToSend;
      if (mediaUrlToSend) payload.media_url = mediaUrlToSend;

      const res = await fetch(`${API_BASE}/${fromPhone}/send-message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();

      if (data.success) {
        setChatMessages(prev => {
          const updatedMessages = [...(prev[selectedChatContact.phone] || [])];
          const index = updatedMessages.findIndex(m => m.id === newMsg.id);
          if (index !== -1) {
            updatedMessages[index] = { ...updatedMessages[index], status: 'sent', media_url: mediaUrlToSend };
          }
          return { ...prev, [selectedChatContact.phone]: updatedMessages };
        });
      } else {
        addNotification(`❌ Error sending message: ${data.message}`, 'error');
      }
    } catch (error) {
      console.error('Send message error:', error);
      addNotification('❌ Network error sending message.', 'error');
    } finally {
      setIsSendingMessage(false);
    }
  };

