    if (!phone) return;
    try {
      const response = await fetch(`http://localhost:5000/api/user/${phone}/disable-account`, {
        method: 'POST'
      });
      if (response.ok) {
        addNotification('Account deactivated successfully.', 'success');
        handleLogout();
      } else {
        addNotification('Failed to deactivate account.', 'error');
      }
    } catch (err) {
      addNotification('Network error.', 'error');
    }
