  const renderChat = () => {
    if (selectedChatContact) {
      const messages = chatMessages[selectedChatContact.phone] || [];

      return (
        <div className="chat-view">
          <div className="chat-header-whatsapp">
            <div className="chat-header-left">
              <button className="btn-back-chat" onClick={goBackToContactList}>←</button>
              <div 
                className="chat-avatar" 
                onClick={() => viewUserProfile(selectedChatContact)}
                style={selectedChatContact.profile_picture_url ? { cursor: 'pointer', backgroundImage: `url(${selectedChatContact.profile_picture_url})`, backgroundSize: 'cover', backgroundPosition: 'center', color: 'transparent' } : { cursor: 'pointer' }}
              >
                {selectedChatContact.profile_picture_url ? '' : (selectedChatContact.name?.charAt(0) || '?')}
              </div>
              <div className="chat-contact-info">
                <div className="chat-contact-name" onClick={() => viewUserProfile(selectedChatContact)}>
                  {selectedChatContact.name}
                </div>
                <div className="chat-contact-status">
                  {selectedChatContact.online ? '🟢 Online' : 'Last seen recently'}
                </div>
              </div>
            </div>
            <div className="chat-header-right">
              <button className="btn-chat-action" onClick={() => viewUserProfile(selectedChatContact)}>👤</button>
            </div>
          </div>

          <div className="chat-messages-whatsapp">
            {messages.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">💬</div>
                <h3>No Messages Yet</h3>
                <p>Start a conversation with {selectedChatContact.name}</p>
              </div>
            ) : (
              messages.map((msg) => (
                <div key={msg.id} className={`message-bubble ${msg.isMine ? 'sent' : 'received'}`}>
                  {!msg.isMine && <div className="message-sender">{msg.sender}</div>}
                  <div className="message-content">
                    {msg.media_url && (
                      <div className="message-media" style={{ marginBottom: '8px' }}>
                        <img 
                          src={msg.media_url} 
                          alt="Attached media" 
                          style={{ maxWidth: '100%', borderRadius: '8px' }} 
                        />
                      </div>
                    )}
                    <p>{msg.message}</p>
                    <span className="message-time">{msg.time}</span>
                    {msg.isMine && msg.status === 'sending' && (
                      <span className="message-status">⏳</span>
                    )}
                    {msg.isMine && msg.status === 'sent' && (
                      <span className="message-status">✓</span>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>

          {chatMediaPreview && (
            <div style={{ padding: '10px', backgroundColor: '#e9edef', borderBottom: '1px solid #ddd', display: 'flex', alignItems: 'center' }}>
              <img src={chatMediaPreview} alt="Preview" style={{ height: '60px', borderRadius: '5px', marginRight: '10px' }} />
              <button 
                onClick={() => { setChatMediaFile(null); setChatMediaPreview(null); }}
                style={{ background: 'none', border: 'none', color: '#ff3b30', cursor: 'pointer', fontWeight: 'bold' }}
              >
                ✕ Remove
              </button>
            </div>
          )}
          <div className="chat-input-whatsapp">
            <input 
              type="file" 
              accept="image/*" 
              id="chat-media-upload" 
              style={{ display: 'none' }}
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  setChatMediaFile(file);
                  setChatMediaPreview(URL.createObjectURL(file));
                }
                e.target.value = null; // reset
              }}
            />
            <button 
              className="btn-attach" 
              onClick={() => document.getElementById('chat-media-upload').click()}
              disabled={isSendingMessage}
              style={{ background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer', padding: '0 10px', color: '#54656f' }}
            >
              📎
            </button>
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder={`Message ${selectedChatContact.name}...`}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  sendMessage();
                }
              }}
              disabled={isSendingMessage}
            />
            <button 
              className="btn-send-whatsapp" 
              onClick={sendMessage}
              disabled={(!newMessage.trim() && !chatMediaFile) || isSendingMessage}
            >
              {isSendingMessage ? '⏳' : (
                <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" stroke="none" style={{ marginLeft: '2px' }}>
                  <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"></path>
                </svg>
              )}
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="chat-contact-list-whatsapp">
        <div className="chat-list-header-whatsapp">
          <h3>💬 Chats</h3>
          <span className="chat-list-count">{chatContacts.length} chats</span>
        </div>

        {chatContacts.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">💬</div>
            <h3>No Conversations</h3>
            <p>Start chatting with your matches from the Matches tab</p>
            <button className="btn-primary" onClick={() => setActiveTab('matches')}>
              💕 View Matches
            </button>
          </div>
        ) : (
          <div className="chat-contacts-list">
            {chatContacts.map((contact) => (
              <div 
                key={contact.phone} 
                className="chat-contact-item-whatsapp"
                onClick={() => selectChatContact(contact)}
              >
                <div className="contact-avatar-whatsapp">
                  {contact.name?.charAt(0) || '?'}
                </div>
                <div className="contact-info-whatsapp">
                  <div className="contact-name-whatsapp">{contact.name}</div>
                  <div className="contact-last-message-whatsapp">
                    {contact.lastMessage || 'Start chatting...'}
                  </div>
                </div>
                <div className="contact-meta-whatsapp">
                  <div className="contact-time-whatsapp">{contact.lastMessageTime || 'Now'}</div>
                  {contact.unread > 0 && (
                    <div className="contact-unread-whatsapp">{contact.unread}</div>
                  )}
                  {contact.online && (
                    <div className="contact-online-dot"></div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

